import com.openggf.game.soniccd.level.*;
import com.openggf.game.soniccd.media.CdProgramAssets;
import com.openggf.game.soniccd.objects.*;
import com.openggf.game.soniccd.player.*;
import com.openggf.game.soniccd.resources.CdPlayerArtRuntime;
import org.junit.jupiter.api.Test;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.openggf.game.soniccd.objects.CdObjectState.ByteField.*;
import static com.openggf.game.soniccd.objects.CdObjectState.WordField.*;

/** Tests FIRST; Java UNRUN. Actual USA C/D assets and actual cached component/Frame/pool algorithms.
 * Complete State/Environment/saved bank/reserved/CPU values and the semantic caller below are explicitly
 * CONSTRUCTED COMPONENT INPUTS, not natural programme/FULL/World ingress. The actual pass creates every
 * private dispatch/Adoption/Plc receipt; no reflection, fake component invocation, effects replay or
 * fabricated private receipt establishes authority. Root owns later real Core/Host/World qualification. */
class TestSonicCdAct3FutureBossPass {
    @Test void absentActualBossFlagPreimageStopsAtTheNativeFirstRead()throws Exception {for(var a:actual()){var h=new Host(a);h.bossFlags=OptionalInt.empty();seed(h,2);var before=h.placement.capture();var actor=h.frame.captureActor();var shared=h.frame.captureShared();var stopped=assertThrows(SonicCdAct3FutureObjectPass.Unowned.class,h::walk);assertEquals(SonicCdAct3FutureObjectPass.Boundary.BOSS_FLAGS,stopped.boundary());samePlacement(before,h.placement);assertEquals(actor,h.frame.captureActor());assertEquals(shared,h.frame.captureShared());assertFalse(h.pass.isCurrentBossOwnersRead());}}
    @Test void unknownTargetRightRetainsOnlyEarlierActualFrameAndTargetBottomStores()throws Exception {for(var a:actual()){var h=new Host(a);h.targetRight=OptionalInt.empty();seed(h,2);var stopped=assertThrows(SonicCdAct3FutureObjectPass.Unowned.class,h::walk);assertEquals(SonicCdAct3FutureObjectPass.Boundary.TARGET_RIGHT_BOUND,stopped.boundary());assertEquals(0x310,h.frame.environment().movement().bounds().bottom());assertEquals(0x310,h.targetBottom);assertEquals(0xAC0,h.frame.environment().movement().bounds().right());assertTrue(h.targetRight.isEmpty());}}
    @Test void actualPendingBossPreflightsAcceptOwnPortAndRejectCaughtReentry()throws Exception {for(var a:actual()){var h=new Host(a);seed(h,2);h.beforeAdopt=()->{h.lastAdoption.validateBefore();assertThrows(IllegalStateException.class,()->h.pass.runWalk(0));var e=h.lastAdoption.bossExpected();if(e!=null){var equal=new SonicCdAct3FutureObjectPass.BossOwners(e.hostFence(),e.coreFence(),e.bossFlagsByte(),e.targetBottomWord(),e.targetLeftWord(),e.targetRightWord(),e.score(),e.normalPalette());assertFalse(h.pass.isCurrentBossOwnerPublication(equal,h.lastAdoption.bossNext()));}};h.walk();assertEquals(0xAC0,h.targetRight.orElseThrow());h.finish();assertFalse(h.frame.closed());}}
    @Test void originalCompletedCallAndAdoptionRetireWithoutPublicValueAuthority()throws Exception {for(var a:actual()){var h=new Host(a);seed(h,2);h.walk();assertNotNull(h.retainedBoss);assertFalse(h.pass.isCurrentBossOperation(h.retainedBoss));if(h.retainedBoss instanceof CdR13Boss.StoreCall c)assertThrows(IllegalStateException.class,()->c.complete(0x1000,0x310));else fail("First issued adoption belongs to native bottom store");assertThrows(IllegalStateException.class,h.lastAdoption::validateBefore);assertThrows(IllegalStateException.class,h.lastAdoption::applyNative);h.finish();}}
    @Test void staleFullFrameOrPoolRejectsBeforeOriginalPreparedStore()throws Exception {for(var a:actual())for(boolean pool:new boolean[]{false,true}){var h=new Host(a);seed(h,2);h.beforeAdopt=()->{if(pool)h.placement.pool().write(h.placement.pool().state(126).moveByte(SUBTYPE,1));else{int value=h.frame.environment().movement().globals().primaryAngle();h.frame.applyPreparedObjectSolidPublication(h.frame.prepareObjectPrimaryAngle(value,(value+1)&255));}};assertThrows(IllegalArgumentException.class,h::walk);assertEquals(0x1000,h.frame.environment().movement().bounds().bottom());assertEquals(0x1000,h.targetBottom);assertThrows(IllegalStateException.class,h.lastAdoption::applyNative);}}
    @Test void originalRuntimeAndErrorKeepEarlierFramePrefixAndRetireOriginalCallbacks()throws Exception {for(var a:actual())for(Throwable original:List.of(new IllegalArgumentException("Boss Host store"),new AssertionError("Boss Host store"))){var h=new Host(a);seed(h,2);h.beforeAdopt=()->{if(h.lastAdoption.bossCall()!=null&&h.lastAdoption.bossCall().site()==CdR13Boss.Site.BOTTOM_TARGET_STORE){if(original instanceof RuntimeException e)throw e;throw(Error)original;}};assertSame(original,assertThrows(Throwable.class,h::walk));assertEquals(0x310,h.frame.environment().movement().bounds().bottom());assertEquals(0x1000,h.targetBottom);assertThrows(IllegalStateException.class,h.lastAdoption::applyNative);assertFalse(h.pass.isCurrentBossOwnersRead());}}
    @Test void missingRealCoreDoesNotManufacturePlcCompletionAfterPrelude()throws Exception {for(var a:actual()){var h=new Host(a);seed(h,0);var stopped=assertThrows(SonicCdAct3FutureObjectPass.Unowned.class,h::walk);assertEquals(SonicCdAct3FutureObjectPass.Boundary.BOSS_PLC_OWNER,stopped.boundary());assertEquals(4,stopped.value());assertEquals(0,h.placement.pool().state(127).routine());assertEquals(0,h.frame.environment().movement().bounds().bossFight());assertEquals(0x310,h.frame.environment().movement().bounds().bottom());}}
    private static void seed(Host h,int routine){var data=CdR13BossAssets.bind(h.assets);h.seedDynamic(127,0x2A,0);h.placement.pool().write(h.placement.pool().state(127).moveByte(ROUTINE,routine).moveByte(ANIMATION,routine==0?0:1).moveByte(SPRITE_FLAGS,4).moveByte(PRIORITY,6).moveByte(WIDTH,0x14).moveByte(Y_RADIUS,8).moveWord(X,0xC52).moveWord(Y,0x78).moveWord(TILE,0x3FD).moveLong(CdObjectState.LongField.MAPPINGS,data.range(CdR13BossAssets.Table.EGGMAN_MAPPINGS).nativeAddress()));}
    private static final class Host implements SonicCdAct3FutureObjectPass.Host {
        final CdR13FutureAssets assets;final CdR13ObjectAssets objects;final CdObjectPlacementRuntime placement;final CdPlayerFrameRuntime frame;final SonicCdAct3FutureObjectPass pass;
        final Object programme=new Object();CdRingGlobals ring=new CdRingGlobals(0,3,0,0,0,0,0,0);CdAssetBytes reserved=CdAssetBytes.copyOf(new byte[1984]),cpu=CdAssetBytes.copyOf(new byte[640]);Optional<CdObjectDrawQueue.CpuSat> completed=Optional.empty();List<SonicCdGameModule.PastSound> sounds=List.of();OptionalInt good=OptionalInt.empty();int scroll=0x33A5;CdPlayerBody.ContactGlobals contact=new CdPlayerBody.ContactGlobals(0,0,0);Optional<CdGlobalObjectAnimation.Extras> animations=Optional.empty();Object fence=new Object();Object bossHostFence=new Object(),bossCoreFence=new Object();OptionalInt bossFlags=OptionalInt.of(0),targetRight=OptionalInt.of(0x1000);int targetBottom=0x1000,targetLeft=0;CdOpeningObjectRuntime.ScoreGlobals score=new CdOpeningObjectRuntime.ScoreGlobals(0,5000,0);CdAssetBytes normal=CdAssetBytes.copyOf(new byte[128]);CdR13Boss.Call retainedBoss;boolean active;Runnable beforeAdopt=()->{};Throwable fault;
        SonicCdAct3FutureObjectPass.Adoption lastAdoption;SonicCdAct3FutureObjectPass.PlcSubmission lastPlc;
        Host(CdR13FutureAssets a){this(a,new CdPlayerFrameRuntime.VIntClock(OptionalLong.of(0),0));}
        Host(CdR13FutureAssets a,CdPlayerFrameRuntime.VIntClock clock){assets=a;objects=CdR13ObjectAssets.fromAssets(a);placement=CdObjectPlacementRuntime.fromAct3FutureAssets(a,bank());frame=CdPlayerFrameRuntime.fromAct3FutureEntry(a,state(),environment(),art(),clock);pass=new SonicCdAct3FutureObjectPass(this,a,objects,frame,placement);}
        public void validate(SonicCdAct3FutureObjectPass p,CdPlayerFrameRuntime f,CdR13FutureAssets a,CdR13ObjectAssets o,CdObjectPlacementRuntime v){if(!active||p!=pass||f!=frame||a!=assets||o!=objects||v!=placement)throw new IllegalStateException("No constructed semantic caller scope");}
        public SonicCdAct3FutureObjectPass.Cut read(){return new SonicCdAct3FutureObjectPass.Cut(this,programme,ring,reserved,cpu,completed,sounds,0,0,0,OptionalInt.empty(),good,OptionalInt.empty(),scroll,OptionalLong.empty());}
        public void adopt(SonicCdAct3FutureObjectPass.Adoption a){lastAdoption=a;assertTrue(pass.isCurrentAdoption(a));a.validateBefore();if(retainedBoss==null&&a.bossCall()!=null)retainedBoss=a.bossCall();beforeAdopt.run();if(fault instanceof RuntimeException r)throw r;if(fault instanceof Error e)throw e;var next=a.next();var boss=a.bossNext();var reused=a.reusedNext();if(a.reusedExpected()!=null)assertSame(fence,a.reusedExpected().fence());var nextBossFence=new Object();var nextCoreFence=new Object();a.applyNative();if(boss!=null){bossFlags=boss.bossFlagsByte();targetBottom=boss.targetBottomWord();targetLeft=boss.targetLeftWord();targetRight=boss.targetRightWord();score=boss.score();normal=boss.normalPalette();}bossHostFence=nextBossFence;bossCoreFence=nextCoreFence;if(reused!=null){contact=reused.contact();animations=reused.animations();fence=new Object();}ring=next.ring();reserved=next.reservedSlots();cpu=next.cpuSat();completed=next.completedCpu();sounds=next.sounds();scroll=next.scrollLockWord();}
        public SonicCdAct3FutureObjectPass.ReusedOwners reusedOwners(SonicCdAct3FutureObjectPass.ReusedOwners expected){assertTrue(pass.isCurrentReusedOwnersRead());if(expected!=null)assertSame(fence,expected.fence());return new SonicCdAct3FutureObjectPass.ReusedOwners(fence,contact,animations);}
        public SonicCdAct3FutureObjectPass.BossOwners bossOwners(SonicCdAct3FutureObjectPass.BossOwners expected){assertTrue(pass.isCurrentBossOwnersRead());return new SonicCdAct3FutureObjectPass.BossOwners(bossHostFence,bossCoreFence,bossFlags,targetBottom,targetLeft,targetRight,score,normal);}
        public void primary(SonicCdAct3FutureObjectPass.PrimaryCall c){fail("Constructed test actor ID0 does not dispatch primary; real World owns it");}
        public void submitTitlePlc(SonicCdAct3FutureObjectPass.PlcSubmission p){lastPlc=p;p.validate();throw p.unowned();}
        void walk(){active=true;try{pass.runWalk(frame.environment().globals().levelFrames());}finally{active=false;}}
        void finish(){active=true;try{pass.finishDraw(new CdObjectDrawQueue.DrawCameras(new CdObjectDrawQueue.CameraWords(0,0),new CdObjectDrawQueue.CameraWords(0,0),new CdObjectDrawQueue.CameraWords(0,0)));}finally{active=false;}}
        CdAssetBytes reserved(int whole){return reserved.slice((whole-1)*64,64);}
        void seedReserved(int whole,int id,int subtype){updateReserved(whole,b->{b[0]=(byte)id;b[0x28]=(byte)subtype;});}
        void updateReserved(int whole,java.util.function.Consumer<byte[]> change){var all=reserved.copy();var row=Arrays.copyOfRange(all,(whole-1)*64,whole*64);change.accept(row);System.arraycopy(row,0,all,(whole-1)*64,64);reserved=CdAssetBytes.copyOf(all);}
        void seedDynamic(int whole,int id,int subtype){var s=placement.pool().state(whole).moveByte(ID,id).moveByte(SUBTYPE,subtype);placement.pool().write(s);}
    }
    private static List<CdR13FutureAssets> retained;
    private static CdR12bTerrainAssets legacy;
    private static synchronized List<CdR13FutureAssets> actual()throws Exception{if(retained!=null)return retained;String root=System.getProperty("soniccd.media.root");org.junit.jupiter.api.Assumptions.assumeTrue(root!=null&&!root.isBlank(),"Optional USA CD media absent");assertTrue(Files.isDirectory(Path.of(root)),"Configured bad root hard fails");List<Path> cues;try(var files=Files.list(Path.of(root).resolve("USA"))){cues=files.filter(p->p.getFileName().toString().toLowerCase(Locale.ROOT).endsWith(".cue")).toList();}assertEquals(1,cues.size());try(var p=CdProgramAssets.open(cues.getFirst(),Optional.of(CdReleaseVariant.USA),Optional.empty())){retained=List.of(CdR13FutureAssets.fromPrograms(p,CdStagePayload.R13C.stage()),CdR13FutureAssets.fromPrograms(p,CdStagePayload.R13D.stage()));legacy=CdR12bTerrainAssets.fromPrograms(p);}return retained;}
    private static CdAssetBytes bank(){byte[] b=new byte[CdObjectPlacementRuntime.SAVED_BANK_BYTES];Arrays.fill(b,(byte)0x2A);return CdAssetBytes.copyOf(b);}
    private static CdPlayerArtRuntime.State art(){byte[] b=new byte[0x300];for(int i=0;i<b.length;i++)b[i]=(byte)(i*7+3);return new CdPlayerArtRuntime.State(b,b,7,true);}
    private static CdPlayerBody.State state(){return new CdPlayerBody.State(new CdPlayerMotionState(0,0,0,0,0,0,0,0,0,9,19,0,0,0,0,0,0,0,0,0),new CdPlayerBody.AnimationCursor(0,0,0),new CdPlayerBody.Header(0,0x22DF20,0,2,16),new CdPlayerBody.Timers(0,0,0,0),new CdPlayerBody.History(CdAssetBytes.copyOf(new byte[256]),0),0,new CdPlayerBody.ObjectLinks(0,0),0x89);}
    private static CdPlayerBody.Environment environment(){return new CdPlayerBody.Environment(new CdPlayerMovement.Environment(new CdPlayerMovement.Physics(0x600,0xC,0x80),new CdPlayerMovement.Bounds(0,0x1000,0x1000,0),new CdPlayerMovement.Gates(2,2,0,0,0,0,0),new CdPlayerMovement.Globals(0,0x60,0x12,0x34,0,0,0,0,0,0)),new CdPlayerBody.Controls(0,0,0,0,1),new CdPlayerBody.Globals(0,0,1,0,7,0,0,0),CdPlayerBody.DynamicSlots.UNIMPLEMENTED);}
    private static void samePlacement(CdObjectPlacementRuntime.Snapshot before,CdObjectPlacementRuntime p){var now=p.capture();assertEquals(before.status(),now.status());assertEquals(before.pool().slots(),now.pool().slots());assertArrayEquals(before.savedFlags().copy(),now.savedFlags().copy());}
    private static void putWord(byte[] b,int at,int v){b[at]=(byte)(v>>>8);b[at+1]=(byte)v;}
}
